CREATE DATABASE holistic_optimization; USE holistic_optimization; CREATE TABLE keyword (id INT(4) NOT NULL PRIMARY KEY, keyword CHAR(100) NOT NULL, phonetic_code CHAR(5)); IMPORT INTO keyword DSV "benchmark/job/data/keyword.csv" ROWS 134170 DELIMITER ","; CREATE INDEX id_keyword ON keyword (id); CREATE INDEX keyword_keyword ON keyword (keyword); CREATE INDEX phonetic_code_keyword ON keyword (phonetic_code); CREATE TABLE movie_info (id INT(4) NOT NULL PRIMARY KEY, movie_id INT(4) NOT NULL, info_type_id INT(4) NOT NULL, info CHAR(100) NOT NULL, note CHAR(100)); IMPORT INTO movie_info DSV "benchmark/job/data/movie_info.csv" ROWS 14835720 DELIMITER ","; CREATE INDEX id_movie_info ON movie_info (id); CREATE INDEX movie_id_movie_info ON movie_info (movie_id); CREATE INDEX info_type_id_movie_info ON movie_info (info_type_id); CREATE INDEX info_movie_info ON movie_info (info); CREATE INDEX note_movie_info ON movie_info (note); CREATE TABLE movie_keyword (id INT(4) NOT NULL PRIMARY KEY, movie_id INT(4) NOT NULL, keyword_id INT(4) NOT NULL); IMPORT INTO movie_keyword DSV "benchmark/job/data/movie_keyword.csv" ROWS 4523930 DELIMITER ","; CREATE INDEX id_movie_keyword ON movie_keyword (id); CREATE INDEX movie_id_movie_keyword ON movie_keyword (movie_id); CREATE INDEX keyword_id_movie_keyword ON movie_keyword (keyword_id); CREATE TABLE title (id INT(4) NOT NULL PRIMARY KEY, title CHAR(100) NOT NULL, imdb_index CHAR(5), kind_id INT(4) NOT NULL, production_year INT(4), imdb_id INT(4), phonetic_code CHAR(5), episode_of_id INT(4), season_nr INT(4), episode_nr INT(4), series_years CHAR(49), md5sum CHAR(32)); IMPORT INTO title DSV "benchmark/job/data/title.csv" ROWS 2528312 DELIMITER ","; CREATE INDEX id_title ON title (id); CREATE INDEX title_title ON title (title); CREATE INDEX imdb_index_title ON title (imdb_index); CREATE INDEX kind_id_title ON title (kind_id); CREATE INDEX production_year_title ON title (production_year); CREATE INDEX imdb_id_title ON title (imdb_id); CREATE INDEX phonetic_code_title ON title (phonetic_code); CREATE INDEX episode_of_id_title ON title (episode_of_id); CREATE INDEX season_nr_title ON title (season_nr); CREATE INDEX episode_nr_title ON title (episode_nr); CREATE INDEX series_years_title ON title (series_years); CREATE INDEX md5sum_title ON title (md5sum); SELECT t.title FROM     keyword AS k,     movie_info AS mi,     movie_keyword AS mk,     title AS t WHERE     k.keyword LIKE "%sequel%" AND     (mi.info = "Sweden" OR mi.info = "Norway" OR mi.info = "Denmark" OR mi.info = "Germany" OR mi.info = "Swedish" OR mi.info = "Norwegian" OR mi.info = "Denish" OR mi.info = "German") AND     t.production_year > 2005 AND     k.id = mk.keyword_id AND     t.id = mk.movie_id AND     t.id = mi.movie_id AND     mk.movie_id = mi.movie_id;